HYDRO_ANS=[
'La taille du crâne doit être replacée dans sa trajectoire et confrontée au développement, à l’examen et aux compartiments liquidiens concernés. Une macrocrânie familiale est un diagnostic différent.',
'Localiser l’obstacle et rechercher les conséquences en amont. Une infection ou une hémorragie peut perturber plusieurs étapes ; la classification n’est pas toujours binaire.',
'Reporter plusieurs mesures fiables et les comparer au poids et à la taille. L’accélération est plus informative qu’un chiffre unique, sans remplacer les signes neurologiques.',
'Après fermeture des sutures, l’expansion crânienne ne peut plus servir de signal précoce fiable. Céphalées, vomissements, vision et vigilance deviennent essentiels au tri.',
'Associer les signes et leur tempo fait craindre une décompensation. Orienter en urgence et ne pas attendre une nouvelle mesure ou une imagerie élective.',
'Une image prise lorsque l’enfant allait bien fournit une référence. L’absence de différence spectaculaire ne suffit toutefois pas à exclure une panne chez un enfant symptomatique.',
'Elle permet une première évaluation sans irradiation. Une réponse incomplète sur la cause ou un contexte préoccupant nécessite une stratégie complémentaire.',
'Le bénéfice d’un examen sans irradiation ne doit pas être annulé par un retard dangereux. L’équipe choisit l’examen disponible qui répond à l’urgence clinique.',
'Un gradient de pression lié à un obstacle peut rendre le geste dangereux. Le mot « mesure de pression » n’est pas une indication suffisante à le pratiquer.',
'Elle contourne certains obstacles en reliant le troisième ventricule aux espaces de circulation extracavitaires. Son indication dépend de l’anatomie et sa fermeture secondaire reste possible.',
'La valve et les cathéters forment un circuit interne. La présence du matériel à la radiographie ne démontre pas que le liquide circule correctement.',
'La surveillance reste nécessaire même après des années sans problème. Rechercher également le surdrainage et les manifestations infectieuses selon la présentation.',
'Préciser vigilance, signes focaux et fièvre, récupérer carte et images antérieures et joindre l’équipe. Une cause digestive ne doit pas être retenue automatiquement.',
'Le succès se juge aussi sur la fonction et la trajectoire développementale. Une normalisation d’image n’efface pas d’éventuelles lésions antérieures ni les besoins d’accompagnement.'
]

def enrich(n, content, answers):
    name=f'codex-LOTS-html/LOT_{n:03}/LOT_{n:03}_Phase_B_V0_DX.3.html'
    text=subprocess.check_output(['git','show',BASE+':'+name],cwd=R).decode()
    source_map={18:{1:(12,34),2:(12,),3:(12,),4:(2,34),5:(12,25),6:(12,34),7:(12,),8:(12,),9:(12,),10:(12,),11:(12,25),12:(12,34),13:(12,25,34)},29:{1:(7,20),2:(7,17),3:(7,17),4:(15,19),5:(7,19),6:(7,17),7:(7,),8:(7,20),9:(7,15),10:(7,19),11:(15,17,18,19),12:(17,19),13:(7,15)}}
    # Ajout de la fenêtre manquante de la partie13, sans changer le texte visible.
    if n==18:
        text=text.replace('>Une déformation récente des lignes demande un examen rapide. Distinguer activité', '><button type="button" class="terme" popovertarget="dx3-detail13">Une déformation récente des lignes demande un examen rapide.</button> Distinguer activité')
        window='<div id="dx3-detail13" popover class="fenetre"><div class="barre"><span>Points clés raisonnés</span><button type="button" popovertarget="dx3-detail13" popovertargetaction="hide" aria-label="Fermer">✕</button></div><div class="corps"></div></div>'
        text=text.replace('<div id="dx3-quiz"',window+'\n<div id="dx3-quiz"',1)
        text=text.replace('</style>','\n.illustration h3,.illustration h4,.illustration figcaption,.illustration .definition{color:#142633}.illustration a{color:#075a84}.illustration .definition{margin:auto;inset:10vh auto auto 5vw}.illustration .scene{scroll-margin-top:80px}\n</style>',1)
    for k,body in content.items():
        start=text.index(f'<div id="dx3-detail{k}"')
        pos=text.index('<div class="corps">',start)+len('<div class="corps">')
        add=f'<!-- RENFORCEMENT_SOLO_20261101_P{k} -->'+body+cite(*source_map[n][k])+'\n'
        text=text[:pos]+add+text[pos:]
    qid='dx3-quiz' if n==18 else 'dx3-detail14'
    start=text.index(f'<div id="{qid}"');end=text.index('<section class="ilot c sources">',start)
    sub=text[start:end];i=iter(answers)
    def q(m):return m[1]+m[2]+f'<p><strong>Raisonnement :</strong> {next(i)}</p>'+m[3]
    sub,count=re.subn(r'(<details class="quiz">.*?<summary>.*?</summary>)(.*?)(</details>)',q,sub,flags=re.S)
    assert count==14
    text=text[:start]+sub+text[end:]
    extra={18:[(34,'HUG — DMLA, symptômes et orientation','https://www.hug.ch/atlas-sante/pathologie-et-traitement/degenerescence-maculaire-liee-lage-dmla')],29:[(17,'UKBB — Hydrocéphalie pédiatrique ; mécanismes, symptômes, diagnostic et traitement. Traduction automatique : formulations ambiguës et taux non repris','https://www.ukbb.ch/fr/traitement-prise-en-charge/tableaux-de-maladies/hydrocephalie-hydrocephalie/'),(18,'HUG — Neurochirurgie de l’hydrocéphalie ; principes chirurgicaux','https://www.hug.ch/neurochirurgie/neurochirurgie-hydrocephalie'),(19,'NHS — Hydrocephalus, complications ; signes infectieux et fermeture secondaire de ventriculostomie','https://www.nhs.uk/conditions/hydrocephalus/complications/'),(20,'Risk factors for unchanged ventricles during pediatric shunt malfunction, résumé consulté ; limite d’une taille ventriculaire inchangée','https://pubmed.ncbi.nlm.nih.gov/34560626/')]}[n]
    ix=text.index('</ol></section>',text.index('<section class="ilot c sources">'))
    li=''.join(f'<li id="s{s}" value="{s}">{title}. <a href="{url}">Source</a>. Consulté le 01.11.2026.</li>\n' for s,title,url in extra)
    text=text[:ix]+li+text[ix:]
    assert '\u00a0' not in text and '\u202f' not in text
    (R/name).write_text(text)

def image_valve():
    p=B/'LOT_029/LOT_029_Phase_B_V0_DX.3.html';text=p.read_text()
    fragment=(B/'renforcement_medical_20261101/images_neuropediatrie/certas_14-fragment.html').read_text()
    fragment=fragment.replace('lot029-materiel-derivation-certas','dx3-materiel-derivation-certas')
    window='<div id="dx3-image-valve" popover class="fenetre"><div class="barre"><span>Matériel de dérivation : marqueurs et cathéter</span><button type="button" popovertarget="dx3-image-valve" popovertargetaction="hide" aria-label="Fermer">✕</button></div><div class="corps">'+fragment+'</div></div>'
    i=text.index('<div class="corps">',text.index('<div id="dx3-detail9"'))+len('<div class="corps">')
    text=text[:i]+'<p>Chez un patient déjà dérivé, comparer les <button type="button" class="terme" popovertarget="dx3-image-valve">marqueurs radio-opaques de valve et le segment de cathéter</button> : cliché réel à gauche, copie annotée à droite. Ce support ne montre pas les ventricules.</p>'+text[i:]
    text=text.replace('<section class="ilot c sources">',window+'\n<section class="ilot c sources">')
    text=text.replace('</style>','\n.illustration h3,.illustration h4,.illustration figcaption,.illustration .definition{color:#142633}.illustration a{color:#075a84}.illustration .definition{margin:auto;inset:10vh auto auto 5vw}.illustration .scene{scroll-margin-top:80px}\n</style>',1)
    p.write_text(text)

if __name__=='__main__':
    enrich(18,AMD,AMD_ANS)
    enrich(29,HYDRO,HYDRO_ANS)
    image_valve()
